#!/usr/bin/env bun
import fs from 'node:fs';
import ts from 'typescript';

const files = process.argv.slice(2);
if (!files.length) {
  console.error('usage: bun gate.mjs <file.ts ...>');
  process.exit(2);
}

let violations = 0;
const report = (file, node, sourceFile) => {
  const { line, character } = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
  console.log(`✗ loose equality  ${file}:${line + 1}:${character + 1}`);
  console.log(`    binary expression: ${node.getText(sourceFile).slice(0, 80).replace(/\s+/g, ' ')}`);
  violations++;
};

for (const file of files) {
  const source = fs.readFileSync(file, 'utf8');
  const sourceFile = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const visit = (node) => {
    if (ts.isBinaryExpression(node) && (node.operatorToken.kind === ts.SyntaxKind.EqualsEqualsToken || node.operatorToken.kind === ts.SyntaxKind.ExclamationEqualsToken)) {
      report(file, node, sourceFile);
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
}

if (violations === 0) console.log('✓ loose-equality AST gate clean');
process.exit(violations > 0 ? 1 : 0);
